<script setup lang="ts">
import {usePageActivity} from '../page-activity';
const pageActive=usePageActivity();
import Modal from '../components/Modal.vue';
import EmptyState from '../components/EmptyState.vue';
import DonutChart from '../components/DonutChart.vue';

import { useScopedRefresh } from '../scoped-refresh';
import { isHR } from '../policy';
import { useFeedback } from '../feedback';
import { markDirty } from '../workspace';
import { formatBeijing } from '../presentation';
import { ref, onMounted,computed,onScopeDispose } from 'vue';
import { me } from '../api';
import { courseApi, all, errorText, type Employee } from '../course-api';
interface Rule {id: string|null; effective_from:string;weekdays:number[];start_time:string;end_time:string;grace_minutes:number}
interface Attendance { employee_id:string; month:string;today:string; overview:{total_days:number;items:{name:string;count:number}[]}; items:{id:string;work_date:string;clock_in_at:string;clock_out_at:string|null;late:boolean;early:boolean;missing:boolean}[]; summary:{planned_days:number;leave_days:number;expected_days:number;complete_days:number;late_days:number;early_days:number;missing_days:number;attendance_rate:string|null} }
const month=ref(new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).format(new Date()));
const employee=ref(''), employees=ref<Employee[]>([]), hr=ref(false), busy=ref(true), error=ref(''), notice=ref(''), result=ref<Attendance|null>(null), rules=ref<Rule[]>([]), current=ref<Rule|null>(null);
const ruleOpen=ref(false),ruleHistoryOpen=ref(false);
const rule=ref({effective_from:'',weekdays:[0,1,2,3,4],start_time:'09:00',end_time:'18:00',grace_minutes:10});
const todayRecord=ref<Attendance['items'][number]|null>(null);
const persistentText=computed(()=>todayRecord.value?`今日已完成${todayRecord.value.clock_out_at?'上下班':'上班'}打卡 · 上班 ${formatBeijing(todayRecord.value.clock_in_at)}${todayRecord.value.clock_out_at?' · 下班 '+formatBeijing(todayRecord.value.clock_out_at):''}`:'');
const overviewLabels:Record<string,string>={NORMAL:'正常完整打卡',LATE:'迟到',EARLY:'早退',LATE_EARLY:'迟到且早退',MISSING:'漏卡',APPROVED_LEAVE:'已批准请假',IN_PROGRESS:'待完成',UPCOMING:'未来工作日'};
const overviewColors:Record<string,string>={'正常完整打卡':'#1464f4','迟到':'#c27605','早退':'#b65518','迟到且早退':'#9634aa','漏卡':'#cf3550','已批准请假':'#20996b','待完成':'#6c7c93','未来工作日':'#94b4df'};
const overview=computed(()=>result.value?.overview.items.filter(row=>row.count>0).map(row=>({...row,name:overviewLabels[row.name]||row.name}))||[]);
const display=formatBeijing;
let loadGeneration=0;
async function load(strict=false){const mine=++loadGeneration;busy.value=true;error.value='';try{const selected=employee.value,requestedMonth=month.value;const query=new URLSearchParams({month:requestedMonth,...(selected?{employee_id:selected}:{})});const fresh=await courseApi<Attendance>(`/attendance?${query}`);const own=!selected&&requestedMonth===fresh.today.slice(0,7)?fresh:await courseApi<Attendance>(`/attendance?month=${fresh.today.slice(0,7)}`);const data=await courseApi<{current:Rule;items:Rule[]}>('/attendance/rules');if(mine===loadGeneration){result.value=fresh;todayRecord.value=own.items.find(row=>row.work_date===own.today)||null;current.value=data.current;rules.value=data.items;}}catch(e){if(mine===loadGeneration){result.value=null;todayRecord.value=null;error.value=errorText(e);}if(strict===true)throw e;}finally{if(mine===loadGeneration)busy.value=false;}}
async function punch(action:'in'|'out'){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await courseApi(`/attendance/clock-${action}`,'POST',{});notice.value=action==='in'?'上班打卡成功':'下班打卡成功';employee.value='';await load();}catch(e){const message=errorText(e);await load();error.value=message;}finally{busy.value=false;}}
async function saveRule(){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await courseApi('/attendance/rules','POST',rule.value);ruleOpen.value=false;markDirty('/attendance',false,'rule');notice.value='新考勤规则已保存，将按生效日期应用';await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
function openRule(){error.value='';rule.value={effective_from:'',weekdays:[...(current.value?.weekdays||[0,1,2,3,4])],start_time:current.value?.start_time||'09:00',end_time:current.value?.end_time||'18:00',grace_minutes:current.value?.grace_minutes??10};ruleOpen.value=true;}
onMounted(async()=>{try{hr.value=isHR(await me());if(hr.value)employees.value=await all<Employee>('/employees');await load();}catch(e){error.value=errorText(e);busy.value=false;}});
const {scopeLocked,scopeFailure,retryScope,scopeStyle}=useScopedRefresh(()=>load(true));
// The client calendar only triggers re-fetch; the server's Shanghai date selects the record.
let observedDay=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());
const dayTimer=setInterval(()=>{const day=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());if(day!==observedDay){observedDay=day;if(!document.hidden&&!scopeLocked.value)void retryScope();}},30000);
onScopeDispose(()=>clearInterval(dayTimer));
useFeedback(notice,error,'/attendance');
</script>
<template><div :style="scopeStyle" class="business-page"><p v-if="scopeLocked" class="verification" role="status">{{scopeFailure||'正在加载…'}}<button v-if="scopeFailure" @click="retryScope">重试</button></p><main v-show="!scopeLocked"><div class="section-heading"><h1>考勤管理</h1><div v-if="hr" class="form-actions"><button :disabled="busy" @click="openRule">配置考勤规则</button><button class="secondary" @click="ruleHistoryOpen=true">规则历史</button></div></div><p class="muted">按北京时间记录打卡时间。</p><p v-if="error" class="error feedback" role="alert">{{error}}</p><p v-if="notice" class="success feedback" role="status">{{notice}}</p>
<section class="card"><h2>本人打卡</h2><p v-if="current">当前规则：{{current.weekdays.map(d=>['周一','周二','周三','周四','周五'][d]).join('、')}} · {{current.start_time}}—{{current.end_time}} · 宽限 {{current.grace_minutes}} 分钟</p><p v-if="persistentText&&!notice&&!error" class="persistent-punch" role="status">{{persistentText}}</p><div class="form-actions"><button :disabled="busy" @click="punch('in')">上班打卡</button><button :disabled="busy" @click="punch('out')">下班打卡</button><button v-if="error" class="secondary" @click="error=''">关闭反馈，查看今日状态</button></div></section>
<section class="card"><h2>月度明细与统计</h2><form class="search-row" @submit.prevent="load()"><label>月份<input v-model="month" type="month" required></label><label v-if="hr">员工<select aria-label="员工" v-model="employee"><option value="">本人</option><option v-for="e in employees" :key="e.id" :value="e.id">{{e.employee_no}} · {{e.full_name}}</option></select></label><button :disabled="busy">查询</button></form><p v-if="busy" role="status">加载中…</p>
<template v-if="result&&!busy&&!error"><div class="attendance-overview"><div><dl class="metrics"><dt>计划 / 已批请假 / 应出勤</dt><dd>{{result.summary.planned_days}} / {{result.summary.leave_days}} / {{result.summary.expected_days}} 天</dd><dt>完整打卡 / 迟到 / 早退 / 漏卡</dt><dd>{{result.summary.complete_days}} / {{result.summary.late_days}} / {{result.summary.early_days}} / {{result.summary.missing_days}} 天</dd><dt>月度出勤率</dt><dd>{{result.summary.attendance_rate===null?'N/A（无应出勤日）':result.summary.attendance_rate+'%'}}</dd></dl><p class="muted">出勤率 = 完整打卡天数 ÷（在职期间计划工作日 − 已批准整日假）。本月未来工作日仍在月度分母；未到下班时间不记当天漏卡。</p></div><section class="attendance-donut"><h3>本月出勤概览</h3><DonutChart :items="overview" title="本月出勤概览环形图" unit="天" center-label="计划工作日" empty-text="暂无计划出勤数据" invalid-text="出勤概览暂不可用，请重新查询。" legend-text="当前员工当月计划工作日" :colors="overviewColors"/><p class="muted">图中每天只计一次。正常完整打卡不含迟到、早退；原文字统计的完整打卡包含异常记录。未结束的当天和未来工作日单独显示。</p></section></div>
<div v-if="result.items.length" class="table-scroll"><table><thead><tr><th>日期</th><th>上班（上海）</th><th>下班（上海）</th><th>判定</th></tr></thead><tbody><tr v-for="row in result.items" :key="row.id"><td>{{row.work_date}}</td><td>{{display(row.clock_in_at)}}</td><td>{{display(row.clock_out_at)}}</td><td>{{[row.late?'迟到':'',row.early?'早退':'',row.missing?'漏卡':''].filter(Boolean).join('、')||'正常'}}</td></tr></tbody></table></div><EmptyState v-else-if="!busy&&!error" text="暂无考勤记录" hint="未打卡工作日仍参与漏卡统计。"/></template></section>
<Modal v-if="hr&&ruleOpen" title="配置考勤规则" scope="rule" :busy="busy" :error="error" :concealed="scopeLocked" @retry="retryScope" @close="ruleOpen=false"><p class="muted">新规则从次日或以后生效，不影响以往打卡记录。</p><form data-dirty-scope="rule" @submit.prevent="saveRule"><fieldset :disabled="busy"><div class="form-columns"><label>生效日期<input v-model="rule.effective_from" type="date" required></label><label>迟到宽限（分钟）<input v-model.number="rule.grace_minutes" type="number" min="0" max="120" required></label><label>上班时间<input v-model="rule.start_time" type="time" required></label><label>下班时间<input v-model="rule.end_time" type="time" required></label></div><div class="checks"><label v-for="(day,index) in ['周一','周二','周三','周四','周五']" :key="index"><input v-model="rule.weekdays" type="checkbox" :value="index">{{day}}</label></div><div class="form-actions"><button type="button" class="secondary" data-modal-cancel>取消</button><button>保存新规则</button></div></fieldset></form></Modal>
<Modal v-if="hr&&ruleHistoryOpen" title="考勤规则历史" :track-changes="false" :concealed="scopeLocked" @retry="retryScope" @close="ruleHistoryOpen=false"><ul><li v-for="r in rules" :key="r.id||'default'">{{r.effective_from}} 起：{{r.start_time}}—{{r.end_time}}，宽限 {{r.grace_minutes}} 分钟</li></ul><p v-if="!rules.length" class="muted">使用初始周一至周五 09:00—18:00、宽限10分钟。</p></Modal></main></div></template>
